-- Customizable Skylight service operations: packages, proposals, agreements, projects, task templates, recurring schedules and secure client workspace.

alter table public.skylight_service_catalog
  add column if not exists service_kind text not null default 'one_time' check(service_kind in ('one_time','recurring','hybrid')),
  add column if not exists default_billing_interval text not null default 'one_time' check(default_billing_interval in ('one_time','monthly','quarterly','annual','custom')),
  add column if not exists default_duration_days integer check(default_duration_days is null or default_duration_days between 1 and 3650),
  add column if not exists default_deposit_bps integer not null default 0 check(default_deposit_bps between 0 and 10000),
  add column if not exists default_scope text,
  add column if not exists default_terms text,
  add column if not exists requires_agreement boolean not null default true,
  add column if not exists create_project_on_acceptance boolean not null default true,
  add column if not exists client_portal_enabled boolean not null default true;

update public.skylight_service_catalog
set service_kind=case when pricing_model='monthly' then 'recurring' else service_kind end,
    default_billing_interval=case when pricing_model='monthly' then 'monthly' else default_billing_interval end
where pricing_model='monthly';

create sequence if not exists public.skylight_proposal_number_seq start with 1001;
create sequence if not exists public.skylight_agreement_number_seq start with 1001;
create sequence if not exists public.skylight_project_number_seq start with 1001;

create table if not exists public.skylight_service_packages(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  name text not null, slug text not null, description text, package_price_cents integer check(package_price_cents is null or package_price_cents>=0),
  billing_interval text not null default 'one_time' check(billing_interval in ('one_time','monthly','quarterly','annual','custom')),
  active boolean not null default true, public_visible boolean not null default false, sort_order integer not null default 100,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,slug)
);
create table if not exists public.skylight_service_package_items(
  id uuid primary key default gen_random_uuid(), package_id uuid not null references public.skylight_service_packages(id) on delete cascade,
  service_id uuid not null references public.skylight_service_catalog(id) on delete cascade, quantity numeric(12,2) not null default 1 check(quantity>0), included_note text, sort_order integer not null default 100, created_at timestamptz not null default now(), unique(package_id,service_id)
);
create table if not exists public.skylight_service_task_templates(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
  service_id uuid not null references public.skylight_service_catalog(id) on delete cascade, title text not null, description text, phase text not null default 'delivery',
  offset_days integer not null default 0 check(offset_days between -365 and 3650), priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),
  client_visible boolean not null default false, requires_client_approval boolean not null default false, active boolean not null default true, sort_order integer not null default 100,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.skylight_proposals(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_id uuid not null references public.skylight_clients(id) on delete restrict,
  proposal_number text not null default ('SP-'||lpad(nextval('public.skylight_proposal_number_seq')::text,6,'0')) unique, public_token uuid not null default gen_random_uuid() unique,
  title text not null, status text not null default 'draft' check(status in ('draft','sent','viewed','accepted','declined','expired','converted','cancelled')), currency text not null default 'USD',
  intro text, scope_summary text, terms text, internal_note text, issue_date date not null default current_date, expires_at date, proposed_start_date date,
  subtotal_cents integer not null default 0 check(subtotal_cents>=0), discount_cents integer not null default 0 check(discount_cents>=0), total_cents integer not null default 0 check(total_cents>=0), deposit_required_cents integer not null default 0 check(deposit_required_cents>=0),
  requires_signature boolean not null default true, sent_at timestamptz, viewed_at timestamptz, accepted_at timestamptz, declined_at timestamptz, converted_at timestamptz,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_proposals_tenant_status_idx on public.skylight_proposals(tenant_id,status,created_at desc);
create index if not exists skylight_proposals_client_idx on public.skylight_proposals(client_id,created_at desc);
create table if not exists public.skylight_proposal_items(
  id uuid primary key default gen_random_uuid(), proposal_id uuid not null references public.skylight_proposals(id) on delete cascade, service_id uuid references public.skylight_service_catalog(id) on delete set null,
  service_name_snapshot text, description text not null, detail text, quantity numeric(12,2) not null default 1 check(quantity>0), unit_price_cents integer not null default 0 check(unit_price_cents>=0),
  line_discount_cents integer not null default 0 check(line_discount_cents>=0), line_total_cents integer not null default 0 check(line_total_cents>=0), billing_interval text not null default 'one_time' check(billing_interval in ('one_time','monthly','quarterly','annual','custom')),
  sort_order integer not null default 100, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_proposal_items_proposal_idx on public.skylight_proposal_items(proposal_id,sort_order);
create table if not exists public.skylight_agreements(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_id uuid not null references public.skylight_clients(id) on delete restrict,
  proposal_id uuid not null unique references public.skylight_proposals(id) on delete restrict, agreement_number text not null default ('SA-'||lpad(nextval('public.skylight_agreement_number_seq')::text,6,'0')) unique,
  public_token uuid not null default gen_random_uuid() unique, title text not null, status text not null default 'pending_signature' check(status in ('draft','pending_signature','signed','void','cancelled')), body_snapshot text not null,
  signer_name text, signer_title text, signer_email text, signer_user_id uuid references auth.users(id), signer_ip text, signer_user_agent text, signed_at timestamptz, staff_signed_by uuid references auth.users(id), staff_signed_at timestamptz,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_agreements_client_idx on public.skylight_agreements(client_id,status,created_at desc);
create table if not exists public.skylight_projects(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_id uuid not null references public.skylight_clients(id) on delete restrict,
  proposal_id uuid unique references public.skylight_proposals(id) on delete set null, agreement_id uuid unique references public.skylight_agreements(id) on delete set null,
  project_number text not null default ('PRJ-'||lpad(nextval('public.skylight_project_number_seq')::text,6,'0')) unique, name text not null,
  status text not null default 'pending_payment' check(status in ('pending_payment','onboarding','active','waiting_client','on_hold','review','completed','cancelled')), health text not null default 'on_track' check(health in ('on_track','attention','at_risk','blocked')),
  progress_pct integer not null default 0 check(progress_pct between 0 and 100), start_date date, due_date date, completed_at timestamptz, client_visible_update text, next_client_update_at timestamptz, internal_note text,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_projects_tenant_status_idx on public.skylight_projects(tenant_id,status,due_date);
create index if not exists skylight_projects_client_idx on public.skylight_projects(client_id,status,created_at desc);
create table if not exists public.skylight_project_services(
  id uuid primary key default gen_random_uuid(), project_id uuid not null references public.skylight_projects(id) on delete cascade, service_id uuid references public.skylight_service_catalog(id) on delete set null,
  proposal_item_id uuid references public.skylight_proposal_items(id) on delete set null, name text not null, billing_interval text not null default 'one_time', agreed_amount_cents integer not null default 0 check(agreed_amount_cents>=0), created_at timestamptz not null default now()
);
create table if not exists public.skylight_project_milestones(
  id uuid primary key default gen_random_uuid(), project_id uuid not null references public.skylight_projects(id) on delete cascade, title text not null, description text,
  status text not null default 'planned' check(status in ('planned','in_progress','waiting_client','completed','skipped')), target_date date, completed_at timestamptz, client_visible boolean not null default true, sort_order integer not null default 100,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_project_milestones_project_idx on public.skylight_project_milestones(project_id,sort_order);
create table if not exists public.skylight_project_tasks(
  id uuid primary key default gen_random_uuid(), project_id uuid not null references public.skylight_projects(id) on delete cascade, milestone_id uuid references public.skylight_project_milestones(id) on delete set null,
  service_id uuid references public.skylight_service_catalog(id) on delete set null, title text not null, description text, status text not null default 'todo' check(status in ('todo','in_progress','waiting_client','review','done','cancelled')),
  priority text not null default 'normal' check(priority in ('low','normal','high','urgent')), due_date date, assigned_user_id uuid references auth.users(id), client_visible boolean not null default false, requires_client_approval boolean not null default false,
  client_approved_at timestamptz, client_approved_by uuid references auth.users(id), client_approval_note text, sort_order integer not null default 100,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_project_tasks_project_idx on public.skylight_project_tasks(project_id,status,due_date);
create table if not exists public.skylight_recurring_services(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_id uuid not null references public.skylight_clients(id) on delete restrict,
  project_id uuid references public.skylight_projects(id) on delete set null, service_id uuid references public.skylight_service_catalog(id) on delete set null, proposal_item_id uuid references public.skylight_proposal_items(id) on delete set null,
  name text not null, status text not null default 'planned' check(status in ('planned','active','paused','cancelled','completed')), billing_interval text not null check(billing_interval in ('monthly','quarterly','annual','custom')),
  amount_cents integer not null default 0 check(amount_cents>=0), start_date date, next_invoice_date date, contract_end_date date, auto_renew boolean not null default false, internal_note text,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists skylight_recurring_services_tenant_idx on public.skylight_recurring_services(tenant_id,status,next_invoice_date);
create table if not exists public.skylight_project_messages(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, project_id uuid not null references public.skylight_projects(id) on delete cascade,
  sender_user_id uuid references auth.users(id) on delete set null, sender_type text not null check(sender_type in ('customer','staff','system')), body text not null check(char_length(body) between 1 and 5000), customer_visible boolean not null default true,
  read_by_customer_at timestamptz, read_by_staff_at timestamptz, created_at timestamptz not null default now()
);
create index if not exists skylight_project_messages_project_idx on public.skylight_project_messages(project_id,created_at);
create table if not exists public.skylight_project_activity(
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, client_id uuid references public.skylight_clients(id) on delete set null,
  proposal_id uuid references public.skylight_proposals(id) on delete set null, agreement_id uuid references public.skylight_agreements(id) on delete set null, project_id uuid references public.skylight_projects(id) on delete set null,
  event_type text not null, message text not null, metadata jsonb not null default '{}'::jsonb, actor_user_id uuid references auth.users(id) on delete set null, created_at timestamptz not null default now()
);
create index if not exists skylight_project_activity_tenant_idx on public.skylight_project_activity(tenant_id,created_at desc);

DO $$ declare t text; begin
  foreach t in array array['skylight_service_packages','skylight_service_task_templates','skylight_proposals','skylight_agreements','skylight_projects','skylight_recurring_services','skylight_project_messages','skylight_project_activity'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('drop policy if exists "staff manage %s" on public.%I',t,t);
    execute format('create policy "staff manage %s" on public.%I for all to authenticated using(private.has_tenant_role(tenant_id,array[''staff'',''admin'',''super_admin''])) with check(private.has_tenant_role(tenant_id,array[''staff'',''admin'',''super_admin'']))',t,t);
  end loop;
end $$;

alter table public.skylight_service_package_items enable row level security;
alter table public.skylight_proposal_items enable row level security;
alter table public.skylight_project_services enable row level security;
alter table public.skylight_project_milestones enable row level security;
alter table public.skylight_project_tasks enable row level security;

drop policy if exists "staff manage skylight_service_package_items" on public.skylight_service_package_items;
create policy "staff manage skylight_service_package_items" on public.skylight_service_package_items for all to authenticated using(exists(select 1 from public.skylight_service_packages p where p.id=package_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_service_packages p where p.id=package_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight_proposal_items" on public.skylight_proposal_items;
create policy "staff manage skylight_proposal_items" on public.skylight_proposal_items for all to authenticated using(exists(select 1 from public.skylight_proposals p where p.id=proposal_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_proposals p where p.id=proposal_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight_project_services" on public.skylight_project_services;
create policy "staff manage skylight_project_services" on public.skylight_project_services for all to authenticated using(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight_project_milestones" on public.skylight_project_milestones;
create policy "staff manage skylight_project_milestones" on public.skylight_project_milestones for all to authenticated using(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin'])));
drop policy if exists "staff manage skylight_project_tasks" on public.skylight_project_tasks;
create policy "staff manage skylight_project_tasks" on public.skylight_project_tasks for all to authenticated using(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']))) with check(exists(select 1 from public.skylight_projects p where p.id=project_id and private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin'])));

grant select,insert,update,delete on public.skylight_service_packages,public.skylight_service_package_items,public.skylight_service_task_templates,public.skylight_proposals,public.skylight_proposal_items,public.skylight_agreements,public.skylight_projects,public.skylight_project_services,public.skylight_project_milestones,public.skylight_project_tasks,public.skylight_recurring_services,public.skylight_project_messages,public.skylight_project_activity to authenticated;
revoke all on public.skylight_service_packages,public.skylight_service_package_items,public.skylight_service_task_templates,public.skylight_proposals,public.skylight_proposal_items,public.skylight_agreements,public.skylight_projects,public.skylight_project_services,public.skylight_project_milestones,public.skylight_project_tasks,public.skylight_recurring_services,public.skylight_project_messages,public.skylight_project_activity from anon;

create or replace function private.skylight_set_proposal_item_total() returns trigger language plpgsql set search_path='' as $$ begin new.line_total_cents:=greatest(0,round(new.quantity*new.unit_price_cents)::integer-new.line_discount_cents); new.updated_at:=now(); return new; end$$;
drop trigger if exists skylight_proposal_item_total on public.skylight_proposal_items;
create trigger skylight_proposal_item_total before insert or update of quantity,unit_price_cents,line_discount_cents on public.skylight_proposal_items for each row execute function private.skylight_set_proposal_item_total();
create or replace function private.skylight_recompute_proposal(p_proposal_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_sub integer; v_discount integer; begin select coalesce(sum(line_total_cents),0)::integer into v_sub from public.skylight_proposal_items where proposal_id=p_proposal_id; select discount_cents into v_discount from public.skylight_proposals where id=p_proposal_id; update public.skylight_proposals set subtotal_cents=v_sub,total_cents=greatest(0,v_sub-coalesce(v_discount,0)),updated_at=now() where id=p_proposal_id; end$$;
revoke all on function private.skylight_recompute_proposal(uuid) from public,anon,authenticated;
create or replace function private.skylight_recompute_proposal_trigger() returns trigger language plpgsql security definer set search_path='' as $$ begin perform private.skylight_recompute_proposal(coalesce(new.proposal_id,old.proposal_id)); return coalesce(new,old); end$$;
drop trigger if exists skylight_proposal_items_recompute on public.skylight_proposal_items;
create trigger skylight_proposal_items_recompute after insert or update or delete on public.skylight_proposal_items for each row execute function private.skylight_recompute_proposal_trigger();

create or replace function private.notify_skylight_admins(p_tenant_id uuid,p_title text,p_body text,p_url text,p_event_key text) returns integer language plpgsql security definer set search_path='' as $$ declare r record; v_count integer:=0; v_inserted integer; begin for r in select distinct user_id from public.user_roles where tenant_id=p_tenant_id and role in('admin','super_admin') loop insert into public.notifications(user_id,tenant_id,title,body,action_url,event_key) select r.user_id,p_tenant_id,left(p_title,180),left(p_body,1200),left(coalesce(p_url,'/admin/skylight-operations'),500),left(p_event_key,240) where not exists(select 1 from public.notifications n where n.user_id=r.user_id and n.event_key=left(p_event_key,240)); get diagnostics v_inserted=row_count; v_count:=v_count+v_inserted; end loop; return v_count; end$$;
revoke all on function private.notify_skylight_admins(uuid,text,text,text,text) from public,anon,authenticated;
create or replace function private.notify_skylight_client_users(p_client_id uuid,p_title text,p_body text,p_url text,p_event_key text) returns integer language plpgsql security definer set search_path='' as $$ declare r record; v_tenant uuid; v_count integer:=0; v_inserted integer; begin select tenant_id into v_tenant from public.skylight_clients where id=p_client_id; for r in select distinct a.user_id,u.email from public.skylight_client_portal_access a join auth.users u on u.id=a.user_id where a.client_id=p_client_id and a.status='active' loop insert into public.notifications(user_id,tenant_id,title,body,action_url,event_key) select r.user_id,v_tenant,left(p_title,180),left(p_body,1200),left(coalesce(p_url,'/account/skylight'),500),left(p_event_key,240) where not exists(select 1 from public.notifications n where n.user_id=r.user_id and n.event_key=left(p_event_key,240)); get diagnostics v_inserted=row_count; if v_inserted=1 then v_count:=v_count+1; if nullif(btrim(coalesce(r.email,'')),'') is not null then insert into public.email_outbox(tenant_id,recipient_email,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(v_tenant,r.email,'transactional','skylight_client_update',left(p_title,180),left(p_body,5000),'Open Skylight Workspace','https://central-il-local-pros.vercel.app/account/skylight','queued',now()); end if; end if; end loop; return v_count; end$$;
revoke all on function private.notify_skylight_client_users(uuid,text,text,text,text) from public,anon,authenticated;

create or replace function public.admin_create_skylight_portal_invite(p_client_id uuid,p_base_url text default 'https://central-il-local-pros.vercel.app',p_send_email boolean default true) returns jsonb language plpgsql security definer set search_path='' as $$ declare c public.skylight_clients%rowtype; v_email text; v_token uuid; v_url text; v_base text; v_invite uuid; begin select * into c from public.skylight_clients where id=p_client_id; if c.id is null then raise exception 'Skylight client not found.'; end if; if not private.has_tenant_role(c.tenant_id,array['staff','admin','super_admin']) then raise exception 'Not authorized.'; end if; v_email:=lower(nullif(btrim(coalesce(c.email,'')),'')); if v_email is null then raise exception 'Add a client email before creating portal access.'; end if; update public.skylight_client_portal_invites set revoked_at=now() where client_id=c.id and interest_id is null and used_at is null and revoked_at is null and expires_at>now(); v_token:=gen_random_uuid(); insert into public.skylight_client_portal_invites(tenant_id,client_id,interest_id,token,invite_email,expires_at,invited_by) values(c.tenant_id,c.id,null,v_token,v_email,now()+interval '14 days',auth.uid()) returning id into v_invite; v_base:=regexp_replace(coalesce(nullif(btrim(p_base_url),''),'https://central-il-local-pros.vercel.app'),'/$',''); if v_base !~ '^https://[A-Za-z0-9.-]+(?::[0-9]+)?$' then v_base:='https://central-il-local-pros.vercel.app'; end if; v_url:=v_base||'/skylight-portal/claim?token='||v_token::text; if coalesce(p_send_email,true) then insert into public.email_outbox(tenant_id,business_id,recipient_email,recipient_name,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(c.tenant_id,c.business_id,v_email,c.contact_name,'transactional','skylight_portal_invite','Your Skylight Reflections Marketing workspace is ready','Skylight Reflections Marketing has opened a secure customer workspace for proposals, agreements, projects, tasks, invoices and service updates. Sign in or create your Local Pros account using this email address, then connect your workspace with the secure invitation link.','Connect My Skylight Workspace',v_url,'queued',now()); end if; return jsonb_build_object('ok',true,'invite_id',v_invite,'client_id',c.id,'invite_email',v_email,'invite_url',v_url,'expires_at',now()+interval '14 days'); end$$;
revoke all on function public.admin_create_skylight_portal_invite(uuid,text,boolean) from public,anon;
grant execute on function public.admin_create_skylight_portal_invite(uuid,text,boolean) to authenticated;

create or replace function public.claim_skylight_client_portal_invite(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v public.skylight_client_portal_invites%rowtype; v_uid uuid:=auth.uid(); v_email text; v_is_eddm boolean; begin if v_uid is null then raise exception 'Sign in before accepting this portal invitation.'; end if; select lower(coalesce(auth.jwt()->>'email','')) into v_email; select * into v from public.skylight_client_portal_invites where token=p_token for update; if v.id is null or v.revoked_at is not null or v.used_at is not null or v.expires_at<=now() then raise exception 'This portal invitation is invalid or has expired.'; end if; if lower(v.invite_email)<>v_email then raise exception 'Sign in with the email address that received this portal invitation.'; end if; insert into public.skylight_client_portal_access(tenant_id,client_id,user_id,access_role,status,invited_email,granted_by,accepted_at) values(v.tenant_id,v.client_id,v_uid,'primary','active',v.invite_email,v.invited_by,now()) on conflict(client_id,user_id) do update set status='active',invited_email=excluded.invited_email,accepted_at=coalesce(public.skylight_client_portal_access.accepted_at,now()),updated_at=now(); update public.skylight_client_portal_invites set used_at=now(),used_by=v_uid where id=v.id; v_is_eddm:=v.interest_id is not null; insert into public.notifications(user_id,tenant_id,title,body,action_url,event_key) values(v_uid,v.tenant_id,case when v_is_eddm then 'EDDM portal connected' else 'Skylight workspace connected' end,case when v_is_eddm then 'Your Skylight EDDM campaign is now connected to this account.' else 'Your Skylight Reflections Marketing workspace is now connected to this account.' end,case when v_is_eddm then '/account/eddm' else '/account/skylight' end,(case when v_is_eddm then 'eddm_portal_connected:' else 'skylight_portal_connected:' end)||v.client_id::text||':'||v_uid::text); perform private.notify_skylight_admins(v.tenant_id,case when v_is_eddm then 'EDDM customer joined the portal' else 'Skylight client joined the portal' end,v.invite_email||' connected secure client access.','/admin/skylight-operations','skylight_portal_claimed:'||v.id::text); if v.interest_id is not null then insert into public.skylight_eddm_activity(tenant_id,market_id,interest_id,event_type,message,metadata,actor_user_id) select i.tenant_id,i.market_id,i.id,'portal_claimed','Customer accepted secure EDDM portal access.',jsonb_build_object('user_id',v_uid),v_uid from public.skylight_eddm_interests i where i.id=v.interest_id; end if; return jsonb_build_object('ok',true,'client_id',v.client_id,'interest_id',v.interest_id,'workspace',case when v_is_eddm then 'eddm' else 'skylight' end); end$$;
revoke all on function public.claim_skylight_client_portal_invite(uuid) from public,anon;
grant execute on function public.claim_skylight_client_portal_invite(uuid) to authenticated;

create or replace function private.skylight_agreement_snapshot(p_proposal_id uuid) returns text language sql stable security definer set search_path='' as $$ select concat_ws(E'\n\n','SKYLIGHT REFLECTIONS MARKETING SERVICE AGREEMENT','Proposal: '||p.proposal_number||' — '||p.title,nullif(p.scope_summary,''),'SERVICES',coalesce((select string_agg('• '||pi.description||case when nullif(pi.detail,'') is not null then E'\n  '||pi.detail else '' end||' — $'||to_char(pi.line_total_cents/100.0,'FM999999990.00')||case when pi.billing_interval<>'one_time' then ' / '||pi.billing_interval else '' end,E'\n' order by pi.sort_order,pi.created_at) from public.skylight_proposal_items pi where pi.proposal_id=p.id),'No service items.'),'TOTAL: $'||to_char(p.total_cents/100.0,'FM999999990.00'),case when p.deposit_required_cents>0 then 'REQUIRED DEPOSIT: $'||to_char(p.deposit_required_cents/100.0,'FM999999990.00') else null end,'TERMS',nullif(p.terms,''),'Electronic acceptance confirms the signer is authorized to approve this agreement for the client. Billing and payment remain governed by issued invoices; accepting or signing this agreement does not itself charge a payment method.') from public.skylight_proposals p where p.id=p_proposal_id $$;
revoke all on function private.skylight_agreement_snapshot(uuid) from public,anon,authenticated;
create or replace function private.ensure_skylight_agreement(p_proposal_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; v_id uuid; begin select * into p from public.skylight_proposals where id=p_proposal_id; select id into v_id from public.skylight_agreements where proposal_id=p.id; if v_id is null then insert into public.skylight_agreements(tenant_id,client_id,proposal_id,title,status,body_snapshot,created_by,updated_by) values(p.tenant_id,p.client_id,p.id,p.title||' — Service Agreement','pending_signature',private.skylight_agreement_snapshot(p.id),auth.uid(),auth.uid()) returning id into v_id; end if; return v_id; end$$;
revoke all on function private.ensure_skylight_agreement(uuid) from public,anon,authenticated;
create or replace function private.ensure_skylight_project(p_proposal_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; a public.skylight_agreements%rowtype; v_project uuid; pi record; tt record; v_service_name text; v_due date; begin select * into p from public.skylight_proposals where id=p_proposal_id; select * into a from public.skylight_agreements where proposal_id=p.id; select id into v_project from public.skylight_projects where proposal_id=p.id; if v_project is not null then return v_project; end if; v_due:=coalesce(p.proposed_start_date,current_date)+coalesce((select max(coalesce(s.default_duration_days,30)) from public.skylight_proposal_items x join public.skylight_service_catalog s on s.id=x.service_id where x.proposal_id=p.id),30); insert into public.skylight_projects(tenant_id,client_id,proposal_id,agreement_id,name,status,start_date,due_date,created_by,updated_by) values(p.tenant_id,p.client_id,p.id,a.id,p.title,case when p.deposit_required_cents>0 then 'pending_payment' else 'onboarding' end,p.proposed_start_date,v_due,auth.uid(),auth.uid()) returning id into v_project; for pi in select * from public.skylight_proposal_items where proposal_id=p.id order by sort_order,created_at loop v_service_name:=coalesce(pi.service_name_snapshot,pi.description); insert into public.skylight_project_services(project_id,service_id,proposal_item_id,name,billing_interval,agreed_amount_cents) values(v_project,pi.service_id,pi.id,v_service_name,pi.billing_interval,pi.line_total_cents); if pi.billing_interval in('monthly','quarterly','annual','custom') then insert into public.skylight_recurring_services(tenant_id,client_id,project_id,service_id,proposal_item_id,name,status,billing_interval,amount_cents,start_date,created_by,updated_by) values(p.tenant_id,p.client_id,v_project,pi.service_id,pi.id,v_service_name,'planned',pi.billing_interval,pi.line_total_cents,p.proposed_start_date,auth.uid(),auth.uid()); end if; for tt in select * from public.skylight_service_task_templates where service_id=pi.service_id and active=true order by sort_order,created_at loop insert into public.skylight_project_tasks(project_id,service_id,title,description,status,priority,due_date,client_visible,requires_client_approval,sort_order,created_by,updated_by) values(v_project,pi.service_id,tt.title,tt.description,'todo',tt.priority,coalesce(p.proposed_start_date,current_date)+tt.offset_days,tt.client_visible,tt.requires_client_approval,tt.sort_order,auth.uid(),auth.uid()); end loop; end loop; insert into public.skylight_project_milestones(project_id,title,description,status,target_date,client_visible,sort_order,created_by,updated_by) values (v_project,'Onboarding','Confirm access, assets, goals and kickoff requirements.','planned',coalesce(p.proposed_start_date,current_date),true,10,auth.uid(),auth.uid()),(v_project,'Delivery','Primary service production and implementation.','planned',v_due,true,20,auth.uid(),auth.uid()),(v_project,'Client Review','Client review, approvals and requested revisions where included.','planned',v_due,true,30,auth.uid(),auth.uid()),(v_project,'Completion','Final handoff, reporting or recurring-service transition.','planned',v_due,true,40,auth.uid(),auth.uid()); update public.skylight_proposals set status='converted',converted_at=now(),updated_at=now() where id=p.id; insert into public.skylight_project_activity(tenant_id,client_id,proposal_id,agreement_id,project_id,event_type,message,metadata,actor_user_id) values(p.tenant_id,p.client_id,p.id,a.id,v_project,'project_created','Project workspace created from accepted proposal.',jsonb_build_object('project_status',case when p.deposit_required_cents>0 then 'pending_payment' else 'onboarding' end),auth.uid()); return v_project; end$$;
revoke all on function private.ensure_skylight_project(uuid) from public,anon,authenticated;

create or replace function public.admin_send_skylight_proposal(p_proposal_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; c public.skylight_clients%rowtype; begin select * into p from public.skylight_proposals where id=p_proposal_id; if p.id is null then raise exception 'Proposal not found.'; end if; if not private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']) then raise exception 'Not authorized.'; end if; if p.total_cents<=0 then raise exception 'Add at least one priced proposal item before sending.'; end if; select * into c from public.skylight_clients where id=p.client_id; if nullif(btrim(coalesce(c.email,'')),'') is null then raise exception 'Client email is required.'; end if; update public.skylight_proposals set status='sent',sent_at=coalesce(sent_at,now()),updated_by=auth.uid(),updated_at=now() where id=p.id; insert into public.email_outbox(tenant_id,business_id,recipient_email,recipient_name,message_type,template_key,subject,body,cta_label,cta_url,status,scheduled_for) values(p.tenant_id,c.business_id,c.email,c.contact_name,'transactional','skylight_proposal_sent','Your Skylight proposal is ready','Your proposal from Skylight Reflections Marketing is ready in your secure customer workspace. Review the scope, services, pricing, deposit requirement and terms before accepting. Acceptance does not itself charge a payment method.','Review Proposal','https://central-il-local-pros.vercel.app/account/skylight','queued',now()); perform private.notify_skylight_client_users(p.client_id,'New Skylight proposal','A new Skylight Reflections Marketing proposal is ready for your review.','/account/skylight','skylight_proposal_sent:'||p.id::text); insert into public.skylight_project_activity(tenant_id,client_id,proposal_id,event_type,message,actor_user_id) values(p.tenant_id,p.client_id,p.id,'proposal_sent','Proposal sent to client workspace and email queue.',auth.uid()); return jsonb_build_object('ok',true,'proposal_id',p.id,'status','sent'); end$$;
revoke all on function public.admin_send_skylight_proposal(uuid) from public,anon;
grant execute on function public.admin_send_skylight_proposal(uuid) to authenticated;
create or replace function public.customer_mark_skylight_proposal_viewed(p_proposal_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; begin select * into p from public.skylight_proposals where id=p_proposal_id; if p.id is null or not private.user_has_skylight_client_access(p.client_id,auth.uid()) then raise exception 'Proposal not available.'; end if; if p.status='sent' then update public.skylight_proposals set status='viewed',viewed_at=coalesce(viewed_at,now()),updated_at=now() where id=p.id; end if; return jsonb_build_object('ok',true); end$$;
revoke all on function public.customer_mark_skylight_proposal_viewed(uuid) from public,anon;
grant execute on function public.customer_mark_skylight_proposal_viewed(uuid) to authenticated;
create or replace function public.customer_accept_skylight_proposal(p_proposal_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; v_agreement uuid; v_project uuid; begin select * into p from public.skylight_proposals where id=p_proposal_id for update; if p.id is null or not private.user_has_skylight_client_access(p.client_id,auth.uid()) then raise exception 'Proposal not available.'; end if; if p.status not in('sent','viewed') then raise exception 'This proposal is not awaiting acceptance.'; end if; if p.expires_at is not null and p.expires_at<current_date then update public.skylight_proposals set status='expired',updated_at=now() where id=p.id; raise exception 'This proposal has expired.'; end if; update public.skylight_proposals set status='accepted',accepted_at=now(),viewed_at=coalesce(viewed_at,now()),updated_at=now() where id=p.id; if p.requires_signature then v_agreement:=private.ensure_skylight_agreement(p.id); else v_project:=private.ensure_skylight_project(p.id); end if; perform private.notify_skylight_admins(p.tenant_id,'Skylight proposal accepted','A client accepted proposal '||p.proposal_number||'.','/admin/skylight-operations','skylight_proposal_accepted:'||p.id::text); insert into public.skylight_project_activity(tenant_id,client_id,proposal_id,agreement_id,project_id,event_type,message,actor_user_id) values(p.tenant_id,p.client_id,p.id,v_agreement,v_project,'proposal_accepted','Client accepted the proposal in the secure workspace.',auth.uid()); return jsonb_build_object('ok',true,'agreement_id',v_agreement,'project_id',v_project,'requires_signature',p.requires_signature); end$$;
revoke all on function public.customer_accept_skylight_proposal(uuid) from public,anon;
grant execute on function public.customer_accept_skylight_proposal(uuid) to authenticated;
create or replace function public.customer_sign_skylight_agreement(p_agreement_id uuid,p_signer_name text,p_signer_title text default null,p_signer_ip text default null,p_user_agent text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare a public.skylight_agreements%rowtype; v_project uuid; v_email text; begin select * into a from public.skylight_agreements where id=p_agreement_id for update; if a.id is null or not private.user_has_skylight_client_access(a.client_id,auth.uid()) then raise exception 'Agreement not available.'; end if; if a.status<>'pending_signature' then raise exception 'This agreement is not awaiting signature.'; end if; if char_length(btrim(coalesce(p_signer_name,'')))<2 then raise exception 'Enter the authorized signer name.'; end if; select email into v_email from auth.users where id=auth.uid(); update public.skylight_agreements set status='signed',signer_name=left(btrim(p_signer_name),180),signer_title=nullif(left(btrim(coalesce(p_signer_title,'')),180),''),signer_email=v_email,signer_user_id=auth.uid(),signer_ip=nullif(left(coalesce(p_signer_ip,''),120),''),signer_user_agent=nullif(left(coalesce(p_user_agent,''),1000),''),signed_at=now(),updated_at=now() where id=a.id; v_project:=private.ensure_skylight_project(a.proposal_id); perform private.notify_skylight_admins(a.tenant_id,'Skylight agreement signed','A client electronically accepted agreement '||a.agreement_number||'.','/admin/skylight-operations','skylight_agreement_signed:'||a.id::text); perform private.notify_skylight_client_users(a.client_id,'Agreement signed','Your Skylight service agreement has been recorded. Any required invoice or deposit remains a separate billing step.','/account/skylight','skylight_agreement_signed_client:'||a.id::text); insert into public.skylight_project_activity(tenant_id,client_id,proposal_id,agreement_id,project_id,event_type,message,actor_user_id) values(a.tenant_id,a.client_id,a.proposal_id,a.id,v_project,'agreement_signed','Client electronically accepted the service agreement.',auth.uid()); return jsonb_build_object('ok',true,'project_id',v_project,'agreement_id',a.id); end$$;
revoke all on function public.customer_sign_skylight_agreement(uuid,text,text,text,text) from public,anon;
grant execute on function public.customer_sign_skylight_agreement(uuid,text,text,text,text) to authenticated;
create or replace function public.admin_create_skylight_invoice_from_proposal(p_proposal_id uuid,p_deposit_only boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.skylight_proposals%rowtype; v_invoice uuid; v_number text; v_token uuid; begin select * into p from public.skylight_proposals where id=p_proposal_id; if p.id is null then raise exception 'Proposal not found.'; end if; if not private.has_tenant_role(p.tenant_id,array['staff','admin','super_admin']) then raise exception 'Not authorized.'; end if; if p.status not in('accepted','converted') then raise exception 'Accept the proposal before creating its invoice.'; end if; if coalesce(p_deposit_only,false) and p.deposit_required_cents<=0 then raise exception 'This proposal does not require a deposit.'; end if; insert into public.skylight_invoices(tenant_id,client_id,status,issue_date,due_date,deposit_required_cents,terms,client_note,internal_note,created_by,updated_by) values(p.tenant_id,p.client_id,'draft',current_date,current_date+7,case when p_deposit_only then 0 else p.deposit_required_cents end,p.terms,'Created from proposal '||p.proposal_number||'.','Created from Skylight proposal '||p.id::text||case when p_deposit_only then ' as deposit-only invoice.' else '.' end,auth.uid(),auth.uid()) returning id,invoice_number,public_token into v_invoice,v_number,v_token; if p_deposit_only then insert into public.skylight_invoice_items(invoice_id,description,detail,quantity,unit_price_cents,line_discount_cents,sort_order) values(v_invoice,'Required deposit — '||p.title,'Deposit for accepted proposal '||p.proposal_number||'.',1,p.deposit_required_cents,0,10); else insert into public.skylight_invoice_items(invoice_id,service_id,description,detail,quantity,unit_price_cents,line_discount_cents,sort_order) select v_invoice,service_id,description,detail,quantity,unit_price_cents,line_discount_cents,sort_order from public.skylight_proposal_items where proposal_id=p.id order by sort_order,created_at; end if; insert into public.skylight_project_activity(tenant_id,client_id,proposal_id,event_type,message,metadata,actor_user_id) values(p.tenant_id,p.client_id,p.id,'invoice_created','Draft invoice created from accepted proposal.',jsonb_build_object('invoice_id',v_invoice,'deposit_only',coalesce(p_deposit_only,false)),auth.uid()); return jsonb_build_object('ok',true,'invoice_id',v_invoice,'invoice_number',v_number,'public_token',v_token,'public_url','/invoice/'||v_token::text); end$$;
revoke all on function public.admin_create_skylight_invoice_from_proposal(uuid,boolean) from public,anon;
grant execute on function public.admin_create_skylight_invoice_from_proposal(uuid,boolean) to authenticated;
create or replace function public.customer_update_skylight_task_approval(p_task_id uuid,p_approved boolean,p_note text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare t public.skylight_project_tasks%rowtype; p public.skylight_projects%rowtype; begin select * into t from public.skylight_project_tasks where id=p_task_id; select * into p from public.skylight_projects where id=t.project_id; if t.id is null or not t.client_visible or not t.requires_client_approval or not private.user_has_skylight_client_access(p.client_id,auth.uid()) then raise exception 'Approval item not available.'; end if; update public.skylight_project_tasks set client_approved_at=case when p_approved then now() else null end,client_approved_by=case when p_approved then auth.uid() else null end,client_approval_note=nullif(left(btrim(coalesce(p_note,'')),2000),''),status=case when p_approved then 'done' else 'review' end,updated_at=now() where id=t.id; perform private.notify_skylight_admins(p.tenant_id,case when p_approved then 'Client approved project item' else 'Client requested project changes' end,t.title||case when nullif(btrim(coalesce(p_note,'')),'') is not null then ': '||left(p_note,400) else '' end,'/admin/skylight-operations','skylight_task_approval:'||t.id::text||':'||extract(epoch from now())::bigint::text); return jsonb_build_object('ok',true); end$$;
