create or replace function public.customer_send_skylight_project_message(p_project_id uuid,p_body text) returns jsonb language plpgsql security definer set search_path='' as $$ declare p public.skylight_projects%rowtype; v_id uuid; begin select * into p from public.skylight_projects where id=p_project_id; if p.id is null or not private.user_has_skylight_client_access(p.client_id,auth.uid()) then raise exception 'Project not available.'; end if; if char_length(btrim(coalesce(p_body,''))) not between 1 and 5000 then raise exception 'Message must be between 1 and 5000 characters.'; end if; insert into public.skylight_project_messages(tenant_id,project_id,sender_user_id,sender_type,body,customer_visible) values(p.tenant_id,p.id,auth.uid(),'customer',btrim(p_body),true) returning id into v_id; perform private.notify_skylight_admins(p.tenant_id,'New Skylight client message',left(btrim(p_body),500),'/admin/skylight-operations','skylight_project_message:'||v_id::text); return jsonb_build_object('ok',true,'message_id',v_id); end$$;
revoke all on function public.customer_send_skylight_project_message(uuid,text) from public,anon;
grant execute on function public.customer_send_skylight_project_message(uuid,text) to authenticated;

create or replace function public.get_my_skylight_workspace() returns jsonb language plpgsql security definer set search_path='' as $$ declare v_uid uuid:=auth.uid(); begin if v_uid is null then raise exception 'Sign in required.'; end if; return jsonb_build_object('clients',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'company_name',c.company_name,'contact_name',c.contact_name,'email',c.email,'status',c.status) order by c.company_name) from public.skylight_client_portal_access a join public.skylight_clients c on c.id=a.client_id where a.user_id=v_uid and a.status='active'),'[]'::jsonb),'proposals',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'client_id',p.client_id,'proposal_number',p.proposal_number,'title',p.title,'status',p.status,'intro',p.intro,'scope_summary',p.scope_summary,'terms',p.terms,'issue_date',p.issue_date,'expires_at',p.expires_at,'proposed_start_date',p.proposed_start_date,'subtotal_cents',p.subtotal_cents,'discount_cents',p.discount_cents,'total_cents',p.total_cents,'deposit_required_cents',p.deposit_required_cents,'requires_signature',p.requires_signature,'sent_at',p.sent_at,'viewed_at',p.viewed_at,'accepted_at',p.accepted_at,'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'service_id',i.service_id,'description',i.description,'detail',i.detail,'quantity',i.quantity,'unit_price_cents',i.unit_price_cents,'line_discount_cents',i.line_discount_cents,'line_total_cents',i.line_total_cents,'billing_interval',i.billing_interval) order by i.sort_order,i.created_at) from public.skylight_proposal_items i where i.proposal_id=p.id),'[]'::jsonb)) order by p.created_at desc) from public.skylight_proposals p where p.client_id in(select a.client_id from public.skylight_client_portal_access a where a.user_id=v_uid and a.status='active') and p.status<>'draft' and p.status<>'cancelled'),'[]'::jsonb),'agreements',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'client_id',a.client_id,'proposal_id',a.proposal_id,'agreement_number',a.agreement_number,'title',a.title,'status',a.status,'body_snapshot',a.body_snapshot,'signer_name',a.signer_name,'signer_title',a.signer_title,'signer_email',a.signer_email,'signed_at',a.signed_at,'created_at',a.created_at) order by a.created_at desc) from public.skylight_agreements a where a.client_id in(select x.client_id from public.skylight_client_portal_access x where x.user_id=v_uid and x.status='active')),'[]'::jsonb),'projects',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'client_id',p.client_id,'project_number',p.project_number,'name',p.name,'status',p.status,'health',p.health,'progress_pct',p.progress_pct,'start_date',p.start_date,'due_date',p.due_date,'completed_at',p.completed_at,'client_visible_update',p.client_visible_update,'milestones',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'description',m.description,'status',m.status,'target_date',m.target_date,'completed_at',m.completed_at,'sort_order',m.sort_order) order by m.sort_order,m.created_at) from public.skylight_project_milestones m where m.project_id=p.id and m.client_visible=true),'[]'::jsonb),'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'description',t.description,'status',t.status,'priority',t.priority,'due_date',t.due_date,'requires_client_approval',t.requires_client_approval,'client_approved_at',t.client_approved_at,'client_approval_note',t.client_approval_note,'sort_order',t.sort_order) order by t.sort_order,t.created_at) from public.skylight_project_tasks t where t.project_id=p.id and t.client_visible=true),'[]'::jsonb),'messages',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'sender_type',m.sender_type,'body',m.body,'created_at',m.created_at) order by m.created_at) from public.skylight_project_messages m where m.project_id=p.id and m.customer_visible=true),'[]'::jsonb)) order by p.created_at desc) from public.skylight_projects p where p.client_id in(select a.client_id from public.skylight_client_portal_access a where a.user_id=v_uid and a.status='active')),'[]'::jsonb),'recurring_services',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'client_id',r.client_id,'project_id',r.project_id,'name',r.name,'status',r.status,'billing_interval',r.billing_interval,'amount_cents',r.amount_cents,'start_date',r.start_date,'next_invoice_date',r.next_invoice_date,'contract_end_date',r.contract_end_date,'auto_renew',r.auto_renew) order by r.created_at desc) from public.skylight_recurring_services r where r.client_id in(select a.client_id from public.skylight_client_portal_access a where a.user_id=v_uid and a.status='active')),'[]'::jsonb),'invoices',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'client_id',i.client_id,'invoice_number',i.invoice_number,'status',i.status,'issue_date',i.issue_date,'due_date',i.due_date,'total_cents',i.total_cents,'amount_paid_cents',i.amount_paid_cents,'balance_due_cents',i.balance_due_cents,'deposit_required_cents',i.deposit_required_cents,'public_token',i.public_token,'hosted_invoice_url',i.hosted_invoice_url) order by i.created_at desc) from public.skylight_invoices i where i.client_id in(select a.client_id from public.skylight_client_portal_access a where a.user_id=v_uid and a.status='active')),'[]'::jsonb)); end$$;
revoke all on function public.get_my_skylight_workspace() from public,anon;
grant execute on function public.get_my_skylight_workspace() to authenticated;

comment on function public.get_my_skylight_workspace() is 'Customer-safe Skylight workspace. Excludes internal notes, staff-only economics, other clients and all Local Pros ranking/verification signals.';
comment on table public.skylight_recurring_services is 'Planned/active recurring service schedule only. It is not a payment authorization or automatic subscription source of truth.';
comment on table public.skylight_proposals is 'Proposal acceptance never charges a payment method. Billing remains explicit through Skylight invoices.';
